typedef struct rt_message {unsigned char *data;size_t length;bool binary;struct rt_message*next;} rt_message;
typedef struct rt_session rt_session;
typedef struct {pthread_mutex_t mu;char device[129],token[257],url[256],base[128],proxy[129],ca[4096];int port;bool allow_local;EVP_PKEY*signing_key;EVP_PKEY*grant_key;rt_session*sessions[4];rt_message*out_first,*out_last;size_t out_count;} rt_runtime;
