 if(!strcmp(type,"START")){if((!strcmp(ft_string(p,"direction"),"upload")&&!s->can_upload)||(!strcmp(ft_string(p,"direction"),"download")&&!s->can_download)){rt_error(s,request,"RTC_AUTH_FAILED");return;}cJSON*body=cJSON_Duplicate(p,true);if(!*ft_string(body,"requestId"))cJSON_AddStringToObject(body,"requestId",ft_string(request,"requestId"));cJSON*out=rt_api(s,request,"POST","/api/v2/transfers",body);cJSON_Delete(body);if(out){if(rt_set_task(s,out,ft_string(out,"resumeToken")))rt_reply(s,request,"READY",out);else{cJSON_Delete(out);rt_error(s,request,"INVALID_RESPONSE");}}return;}
 if(!strcmp(type,"RESUME")||!strcmp(type,"STATUS")){const char*id=ft_string(p,"transferId"),*token=ft_string(p,"resumeToken");if(!ft_hex(id,16)||!ft_hex(token,32)){rt_error(s,request,"INVALID_TRANSFER");return;}char old_resume[65];snprintf(old_resume,sizeof(old_resume),"%s",s->resume);snprintf(s->resume,sizeof(s->resume),"%s",token);char path[192];const char*cursor=ft_string(p,"cursor");if(*cursor&&strspn(cursor,"0123456789")!=strlen(cursor)){snprintf(s->resume,sizeof(s->resume),"%s",old_resume);rt_error(s,request,"INVALID_CURSOR");return;}if(!strcmp(type,"RESUME"))snprintf(path,sizeof(path),"/api/v2/transfers/%s/resume",id);else snprintf(path,sizeof(path),"/api/v2/transfers/%s%s%s",id,*cursor?"?cursor=":"",cursor);cJSON*out=rt_api(s,request,!strcmp(type,"RESUME")?"POST":"GET",path,!strcmp(type,"RESUME")?p:NULL);if(out){if(!strcmp(type,"RESUME")&&!rt_set_task(s,out,token)){cJSON_Delete(out);rt_error(s,request,"INVALID_RESPONSE");}else rt_reply(s,request,!strcmp(type,"RESUME")?"READY":"STATUS",out);}else snprintf(s->resume,sizeof(s->resume),"%s",old_resume);return;}
