 if(!strcmp(type,"COMMIT_BLOCK")){if(strcmp(s->direction,"upload")||s->pending){rt_error(s,request,"TRANSFER_BUSY");return;}s->pending=cJSON_Duplicate(request,true);s->pending_since=time(NULL);rt_commit_pending(s);return;}
 if(!strcmp(type,"READ_BLOCK")){uint64_t index;if(strcmp(s->direction,"download")||!ft_u64(p,"blockIndex",&index)){rt_error(s,request,"INVALID_BLOCK");return;}char path[160];snprintf(path,sizeof(path),"/api/v2/transfers/%s/blocks/%" PRIu64,s->transfer,index);rt_http reply;if(!rt_http_call(s,"GET",path,NULL,0,NULL,&reply)){rt_error(s,request,"FILE_API_UNAVAILABLE");return;}if(reply.status!=200||reply.length>SE9_FT_BLOCK||!ft_hex(reply.hash,32)){free(reply.body);rt_error(s,request,"SNAPSHOT_UNAVAILABLE");return;}int max=rtcMaxMessageSize(s->file);if(max<=0||max>SE9_FT_FRAME)max=SE9_FT_FRAME;if(max<=SE9_FT_HEADER){free(reply.body);rt_error(s,request,"MESSAGE_LIMIT");return;}unsigned char frame[SE9_FT_FRAME];size_t offset=0;bool ok=true;while(offset<reply.length){size_t take=reply.length-offset;if(take>(size_t)max-SE9_FT_HEADER)take=(size_t)max-SE9_FT_HEADER;size_t n=ft_frame_write(frame,sizeof(frame),s->transfer,s->epoch,s->tx_sequence++,index*SE9_FT_BLOCK+offset,reply.body+offset,take);if(!n||!rt_send_channel(s,s->file,frame,n,false)){ok=false;break;}offset+=take;}free(reply.body);if(!ok){rt_error(s,request,"CHANNEL_CLOSED");return;}s->download_index=index;snprintf(s->download_hash,sizeof(s->download_hash),"%s",reply.hash);cJSON*out=cJSON_CreateObject();ft_number(out,"blockIndex",index);ft_number(out,"length",reply.length);cJSON_AddStringToObject(out,"sha256",reply.hash);rt_reply(s,request,"COMMIT_BLOCK",out);return;}
