static void rt_binary(rt_session*s,const unsigned char*data,size_t length){char id[33];uint32_t epoch,sequence;uint64_t offset;const unsigned char*payload;size_t size;pthread_mutex_lock(&s->mu);bool authorized=s->bound&&s->grant_expiry>(int64_t)time(NULL);pthread_mutex_unlock(&s->mu);if(!authorized||strcmp(s->direction,"upload")||!ft_frame_read(data,length,id,&epoch,&sequence,&offset,&payload,&size)||strcmp(id,s->transfer)||epoch!=s->epoch||sequence!=s->rx_sequence||offset>=s->size||size>s->size-offset){rt_stop(s);return;}uint64_t index=offset/SE9_FT_BLOCK;if(s->filled==0)s->block_index=index;if(index!=s->block_index||offset%SE9_FT_BLOCK!=s->filled){rt_stop(s);return;}if(!s->block){s->block=malloc(SE9_FT_BLOCK);if(!s->block){rt_stop(s);return;}}memcpy(s->block+s->filled,payload,size);s->filled+=size;s->rx_sequence++;rt_commit_pending(s);}
static void*rt_task_worker(void*arg){rt_session*s=arg;for(;;){pthread_mutex_lock(&s->mu);while(!s->closed&&!s->first){struct timespec deadline;clock_gettime(CLOCK_REALTIME,&deadline);deadline.tv_sec++;pthread_cond_timedwait(&s->cond,&s->mu,&deadline);if(s->pending&&time(NULL)-s->pending_since>30)break;}bool closed=s->closed;rt_message*m=s->first;if(m){s->first=m->next;if(!s->first)s->last=NULL;s->queue_bytes-=m->length;}pthread_mutex_unlock(&s->mu);if(closed)break;if(!m){if(s->pending&&time(NULL)-s->pending_since>30){rt_error(s,s->pending,"BLOCK_TIMEOUT");cJSON_Delete(s->pending);s->pending=NULL;s->filled=0;}continue;}if(m->binary)rt_binary(s,m->data,m->length);else{cJSON*request=cJSON_ParseWithLength((char*)m->data,m->length);if(request){rt_control(s,request);cJSON_Delete(request);}else rt_stop(s);}free(m->data);free(m);}return NULL;}
static void rt_on_message(int id,const char*data,int size,void*ptr){rt_session*s=ptr;bool binary=size>=0;size_t length=binary?(size_t)size:strlen(data);if(length>SE9_FT_FRAME||length==0||(binary&&id!=s->file)||(!binary&&id!=s->control)){rt_stop(s);return;}rt_message*m=calloc(1,sizeof(*m));if(!m){rt_stop(s);return;}m->data=malloc(length+1);if(!m->data){free(m);rt_stop(s);return;}memcpy(m->data,data,length);m->data[length]=0;m->length=length;m->binary=binary;pthread_mutex_lock(&s->mu);if(s->closed||s->queue_bytes+length>2*SE9_FT_BLOCK){pthread_mutex_unlock(&s->mu);free(m->data);free(m);rt_stop(s);return;}if(s->last)s->last->next=m;else s->first=m;s->last=m;s->queue_bytes+=length;pthread_cond_signal(&s->cond);pthread_mutex_unlock(&s->mu);}
static void rt_on_channel(int pc,int channel,void*ptr){(void)pc;rt_session*s=ptr;char label[64];if(rtcGetDataChannelLabel(channel,label,sizeof(label))<0){rtcDeleteDataChannel(channel);return;}rtcReliability reliability;if(rtcGetDataChannelReliability(channel,&reliability)!=0||reliability.unordered||reliability.unreliable){rtcDeleteDataChannel(channel);rt_stop(s);return;}pthread_mutex_lock(&s->mu);bool accepted=false;if(!strcmp(label,"se9.control.v1")&&s->control<0){s->control=channel;accepted=true;}else if(!strcmp(label,"se9.file.v1")&&s->file<0){s->file=channel;accepted=true;}pthread_mutex_unlock(&s->mu);if(!accepted){rtcDeleteDataChannel(channel);rt_stop(s);return;}rtcSetMessageCallback(channel,rt_on_message);}
static void rt_on_state(int pc,rtcState state,void*ptr){(void)pc;if(state==RTC_FAILED||state==RTC_CLOSED)rt_stop(ptr);}
static void rt_on_description(int pc,const char*sdp,const char*type,void*ptr){(void)pc;rt_session*s=ptr;if(strcmp(type,"answer"))return;char hash[65],transcript[320];if(!ft_sha256(sdp,strlen(sdp),hash))return;snprintf(transcript,sizeof(transcript),"se9-rtc-v1|%s|%s|%s|%s",s->sid,s->nid,s->offer_hash,hash);EVP_MD_CTX*ctx=EVP_MD_CTX_new();unsigned char signature[64];size_t size=sizeof(signature);bool ok=ctx&&EVP_DigestSignInit(ctx,NULL,NULL,NULL,runtime.signing_key)==1&&EVP_DigestSign(ctx,signature,&size,(unsigned char*)transcript,strlen(transcript))==1;EVP_MD_CTX_free(ctx);if(!ok)return;char*encoded=ft_base64(signature,size,false);cJSON*event=rt_event(s,"session.answer");cJSON*p=cJSON_AddObjectToObject(event,"payload");cJSON*answer=cJSON_AddObjectToObject(p,"answer");cJSON_AddStringToObject(answer,"type","answer");cJSON_AddStringToObject(answer,"sdp",sdp);cJSON_AddStringToObject(p,"deviceSignature",encoded?encoded:"");free(encoded);rt_signal(event);}
