static void rt_process_signal(cJSON*event){const char*type=ft_string(event,"type");if(!strcmp(type,"ping")){cJSON*out=cJSON_CreateObject();cJSON_AddStringToObject(out,"type","pong");rt_signal(out);return;}if(!strcmp(type,"session.invite")||!strcmp(type,"session.renewed")){rt_invite(event);return;}rt_session*s=NULL;for(int i=0;i<4;i++)if(runtime.sessions[i]&&!strcmp(runtime.sessions[i]->sid,ft_string(event,"rtcSessionId"))){s=runtime.sessions[i];break;}if(!s||strcmp(s->nid,ft_string(event,"negotiationId")))return;if(!strcmp(type,"session.close")){rt_stop(s);return;}if(!strcmp(type,"ice.candidate")){cJSON*p=cJSON_GetObjectItemCaseSensitive(event,"payload");const char*candidate=ft_string(p,"candidate");if(*candidate&&strlen(candidate)<4096)rtcAddRemoteCandidate(s->pc,candidate,ft_string(p,"sdpMid"));}}
static void*rt_signaling_worker(void*unused){(void)unused;for(;;){ft_socket ws;char path[512];snprintf(path,sizeof(path),"%s/api/v2/rtc/signaling/device?deviceId=%s",runtime.base,runtime.device);if(!ft_socket_open(&ws,runtime.url,path,"X-Device-Token",runtime.token,runtime.ca,runtime.allow_local)){fprintf(stderr,"[RTC] signaling unavailable; retrying\n");sleep(5);continue;}fprintf(stderr,"[RTC] device signaling connected\n");bool connected=true;while(connected){for(;;){pthread_mutex_lock(&runtime.mu);rt_message*m=runtime.out_first;if(m){runtime.out_first=m->next;if(!runtime.out_first)runtime.out_last=NULL;runtime.out_count--;}pthread_mutex_unlock(&runtime.mu);if(!m)break;connected=ft_socket_send(&ws,1,m->data,m->length);free(m->data);free(m);if(!connected)break;}if(!connected)break;unsigned char*body=NULL;size_t length=0;int result=ft_socket_receive(&ws,&body,&length);if(result<0){free(body);break;}if(result>0){cJSON*event=cJSON_ParseWithLength((char*)body,length);if(event){rt_process_signal(event);cJSON_Delete(event);}free(body);}for(int i=0;i<4;i++){rt_session*s=runtime.sessions[i];if(s&&rt_closed(s)){runtime.sessions[i]=NULL;rt_destroy(s);}}}ft_socket_close(&ws);for(int i=0;i<4;i++){rt_session*s=runtime.sessions[i];runtime.sessions[i]=NULL;rt_destroy(s);}sleep(2);}return NULL;}
bool se9_rtc_start(const char*device_id,EVP_PKEY*device_key,const char*device_token,const char*cloud_url,const char*base_path,int api_port,const char*proxy_secret,const char*ca_file){const char*enabled=getenv("SE9_RTC_ENABLED");if(enabled&&!strcmp(enabled,"0"))return true;if(enabled&&strcmp(enabled,"1")){fprintf(stderr,"[RTC] SE9_RTC_ENABLED must be 0 or 1\n");return false;}if(!device_token[0]||!proxy_secret[0]){fprintf(stderr,"[RTC] registered device token and local proxy key are required\n");return false;}EVP_PKEY*key=se9_load_cloud_grant_key();if(!key){fprintf(stderr,"[RTC] cannot load trusted cloud public key\n");return false;}snprintf(runtime.device,sizeof(runtime.device),"%s",device_id);snprintf(runtime.token,sizeof(runtime.token),"%s",device_token);snprintf(runtime.url,sizeof(runtime.url),"%s",cloud_url);snprintf(runtime.base,sizeof(runtime.base),"%s",base_path);snprintf(runtime.proxy,sizeof(runtime.proxy),"%s",proxy_secret);snprintf(runtime.ca,sizeof(runtime.ca),"%s",ca_file);runtime.port=api_port;runtime.allow_local=getenv("SE9_RTC_ALLOW_INSECURE_LOCAL")&&!strcmp(getenv("SE9_RTC_ALLOW_INSECURE_LOCAL"),"1");runtime.grant_key=key;runtime.signing_key=device_key;EVP_PKEY_up_ref(device_key);rtcInitLogger(RTC_LOG_WARNING,NULL);pthread_t worker;if(pthread_create(&worker,NULL,rt_signaling_worker,NULL)!=0){EVP_PKEY_free(runtime.signing_key);EVP_PKEY_free(runtime.grant_key);runtime.signing_key=runtime.grant_key=NULL;return false;}pthread_detach(worker);return true;}
bool se9_rtc_relay_attach(const void*data,size_t length,se9_relay_principal*principal){memset(principal,0,sizeof(*principal));cJSON*event=cJSON_ParseWithLength(data,length);if(!event||strcmp(ft_string(event,"type"),"relay.attach")){cJSON_Delete(event);return false;}cJSON*p=cJSON_GetObjectItemCaseSensitive(event,"payload");cJSON*g=rt_grant(ft_string(p,"context"),"se9-relay");if(!g){cJSON_Delete(event);return false;}snprintf(principal->user_id,sizeof(principal->user_id),"%s",ft_string(g,"sub"));snprintf(principal->device_id,sizeof(principal->device_id),"%s",ft_string(g,"deviceId"));principal->expires=(int64_t)cJSON_GetObjectItemCaseSensitive(g,"exp")->valuedouble;cJSON_Delete(g);cJSON_Delete(event);return true;}
